#!/usr/bin/env python3
# AI DISCLAIMER: All of the text in this file was generated by AI.
"""W010 runner: time Fcmp::prove for each multiexp arm, one process per arm and case, pinned to one CPU.
Each case is n inputs on a 5-layer tree (kind 1: a full tree, each input in its own leaf chunk), seeds 1-3. Within each
(seed, n) the arm order rotates. Every process verifies the proof it made. Appends to <dir>/results.csv.
usage: run_w010.py <dir with bins/fcmps-<arm>> <cpu> [n,n,...] [seeds]"""
import csv, hashlib, os, re, subprocess, sys, time

base, cpu = os.path.abspath(sys.argv[1]), sys.argv[2]
NS = [int(x) for x in (sys.argv[3] if len(sys.argv) > 3 else "1,2,8,32,128").split(",")]
SEEDS = [int(x) for x in (sys.argv[4] if len(sys.argv) > 4 else "1,2,3").split(",")]
LAYERS, KIND, ARMS = 5, 1, ["m051", "m052", "s4"]
out_csv = os.path.join(base, "results.csv")

def sha(p):
    return hashlib.sha256(open(p, "rb").read()).hexdigest()

exe = {a: os.path.join(base, "bins", "fcmps-" + a) for a in ARMS}
for a in ARMS:
    print("%s %s" % (a, sha(exe[a])), flush=True)
new = not os.path.exists(out_csv)
f = open(out_csv, "a", newline="")
w = csv.writer(f)
if new:
    w.writerow(["utc", "arm", "n_inputs", "layers", "seed", "prove_s", "proof_len", "proof_sha256", "rc", "wall_s"])
k = 0
for seed in SEEDS:
    for n in NS:
        order = ARMS[k % 3:] + ARMS[:k % 3]
        k += 1
        for a in order:
            od = os.path.join(base, "out", a)
            os.makedirs(od, exist_ok=True)
            env = dict(os.environ, DOT3_OUT=od, DOT3_MAX_INPUTS="128", DOT3_CASES="%d:%d:%d:%d" % (n, LAYERS, seed, KIND))
            t0 = time.time()
            utc = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(t0))
            try:
                p = subprocess.run(["taskset", "-c", cpu, exe[a], "--ignored", "--exact", "tests::dot3_diff::dot3_diff",
                                    "--test-threads=1", "--nocapture"], env=env, capture_output=True, text=True, timeout=7200)
                rc, text = p.returncode, p.stdout + p.stderr
            except subprocess.TimeoutExpired:
                rc, text = "timeout", ""
            wall = time.time() - t0
            with open(os.path.join(base, "out", "%s_%d_%d_%d.log" % (a, n, LAYERS, seed)), "w") as lg:
                lg.write(text)
            m = re.search(r"DOT3CASE (\S+) len=(\d+) prove_ms=(\d+) cross=(\S+)", text)
            name = "%d_%d_%d_%d" % (n, LAYERS, seed, KIND)
            binp = os.path.join(od, name + ".bin")
            ok = m is not None and rc == 0 and "test result: ok. 1 passed" in text
            row = [utc, a, n, LAYERS, seed, "%.3f" % (int(m.group(3)) / 1000) if m else "", m.group(2) if m else "",
                   sha(binp) if os.path.exists(binp) else "", rc if not ok else 0, "%.1f" % wall]
            w.writerow(row); f.flush()
            print(",".join(str(x) for x in row) + ("" if ok else "  FAIL"), flush=True)
print("RUN_DONE " + time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()), flush=True)
